// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate/spring

const { fontFamily: interFamily } = loadInter();



export type PercentageGridProps = Record<string, any>;

const PercentageGrid: React.FC<PercentageGridProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  percentage = 84,
  headline = "of people prefer using digital payment methods over traditional cash",
  description = "making it essential for businesses to adapt to modern, secure, and efficient transaction platforms.",
  circleColor = "#FF5500",
  unfilledCircleColor = "#888888",
  textColor = "#FFFFFF",
  descriptionColor = "#AAAAAA",
  columns = 14,
  rows = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  const totalCircles = columns * rows;
  const totalFilledCircles = Math.round((percentage / 100) * totalCircles);

  const durationInFrames = Math.floor(durationInSeconds * fps);
  
  // Timing calculations
  const textEntranceFrame = 10;
  const fillStartFrame = 45;
  const fillEndFrame = Math.min(fillStartFrame + fps * 4, durationInFrames - 30);
  
  // Calculate text counting up
  const currentPercentageText = interpolate(
    frame,
    [fillStartFrame, fillEndFrame],
    [0, percentage],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  // Stagger calculation for grid entrance
  const maxStaggerDuration = 30;
  const staggerDelay = Math.min(0.5, maxStaggerDuration / totalCircles);

  // Precompute fill frames to match the text counting progress
  const circleFillFrames = useMemo(() => {
    return Array.from({ length: totalCircles }).map((_, i) => {
      const isTargetFilled = i < totalFilledCircles;
      if (!isTargetFilled) return Infinity;
      if (totalFilledCircles <= 1) return fillStartFrame;
      return interpolate(i, [0, totalFilledCircles - 1], [fillStartFrame, fillEndFrame]);
    });
  }, [totalCircles, totalFilledCircles, fillStartFrame, fillEndFrame]);

  // Text entrance animations
  const textSpring = spring({ frame: frame - textEntranceFrame, fps, config: { damping: 14 } });
  const textOpacity = interpolate(frame, [textEntranceFrame, textEntranceFrame + 15], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const textY = interpolate(textSpring, [0, 1], [50 * s, 0]);

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: interFamily, 
      padding: 100 * s, 
      display: 'flex', 
      flexDirection: 'column' 
    }}>
      
      {/* Top Section */}
      <div style={{ 
        display: 'flex', 
        flexDirection: 'row', 
        width: '100%', 
        alignItems: 'center', 
        marginBottom: 80 * s,
        opacity: textOpacity,
        transform: `translateY(${textY}px)`,
        transition: "none"
      }}>
        <div style={{ 
          width: '40%', 
          fontSize: 280 * s, 
          fontWeight: 800, 
          color: textColor, 
          letterSpacing: '-0.04em', 
          lineHeight: 1,
          fontVariantNumeric: 'tabular-nums',
          transition: "none"
        }}>
          {Math.round(currentPercentageText)}%
        </div>
        <div style={{ 
          width: '60%', 
          display: 'flex', 
          flexDirection: 'column', 
          gap: 16 * s,
          transition: "none"
        }}>
          <div style={{ fontSize: 56 * s, fontWeight: 700, color: textColor, lineHeight: 1.2, transition: "none" }}>
            {headline}
          </div>
          <div style={{ fontSize: 32 * s, fontWeight: 400, color: descriptionColor, lineHeight: 1.4, maxWidth: '90%', transition: "none" }}>
            {description}
          </div>
        </div>
      </div>

      {/* Bottom Section (Circles Grid) */}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: `repeat(${columns}, 1fr)`, 
        gap: 16 * s,
        width: '100%',
        flex: 1,
        alignContent: 'center',
        transition: "none"
      }}>
        {Array.from({ length: totalCircles }).map((_, i) => {
          const entranceFrame = i * staggerDelay;
          const circleEntranceScale = spring({
            frame: frame - entranceFrame,
            fps,
            config: { damping: 14 }
          });

          const myFillFrame = circleFillFrames[i];
          const fillPop = myFillFrame === Infinity ? 0 : spring({
            frame: frame - myFillFrame,
            fps,
            config: { damping: 12, stiffness: 200 }
          });

          const isVisible = frame >= entranceFrame;
          const isFillVisible = frame >= myFillFrame && myFillFrame !== Infinity;

          return (
            <div key={i} style={{ 
              aspectRatio: 1, 
              backgroundColor: unfilledCircleColor, 
              borderRadius: '50%',
              transform: `scale(${circleEntranceScale})`,
              opacity: isVisible ? 1 : 0,
              position: 'relative',
              transition: "none"
            }}>
              <div style={{
                position: 'absolute',
                top: 0, left: 0, right: 0, bottom: 0,
                backgroundColor: circleColor,
                borderRadius: '50%',
                transform: `scale(${fillPop})`,
                opacity: isFillVisible ? 1 : 0,
                transition: "none"
              }} />
            </div>
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

export default PercentageGrid;